(function(){
  let t=0;
  const warm = PALETTE[0]||'#d4752e';
  const frostC = PALETTE[1]||'#eef3f6';
  const accent = PALETTE[2]||'#c94f5c';

  const notes=[];
  for(let i=0;i<16;i++){
    notes.push({speed:0.28+Math.random()*0.25,size:3+Math.random()*3,offset:Math.random()*1000,trail:[]});
  }
  const motes=[];
  for(let i=0;i<55;i++){
    motes.push({x:Math.random()*W(),y:Math.random()*H(),r:1+Math.random()*2,speed:0.1+Math.random()*0.22,phase:Math.random()*Math.PI*2});
  }
  const frostPoints=[{x:0.08,y:0.1},{x:0.93,y:0.1},{x:0.08,y:0.9},{x:0.93,y:0.88}];

  function drawFrost(cx,cy,scale,growth,color){
    ctx.save();
    ctx.translate(cx,cy);
    ctx.scale(scale,scale);
    ctx.strokeStyle=color;
    ctx.lineWidth=1.2;
    const arms=6;
    for(let a=0;a<arms;a++){
      ctx.save();
      ctx.rotate(a*Math.PI*2/arms + t*0.02);
      ctx.globalAlpha=0.55;
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(0,-growth*42);
      ctx.stroke();
      for(let b=1;b<=3;b++){
        const yy=-growth*42*(b/4);
        const len=growth*11*(1-b/5);
        ctx.beginPath();
        ctx.moveTo(0,yy);
        ctx.lineTo(len,yy-len*0.6);
        ctx.moveTo(0,yy);
        ctx.lineTo(-len,yy-len*0.6);
        ctx.stroke();
      }
      ctx.restore();
    }
    ctx.restore();
  }

  function drawBird(cx,cy,scale,bob,colorBody,colorAccent){
    ctx.save();
    ctx.translate(cx,cy+bob);
    ctx.scale(scale,scale);

    const grad=ctx.createRadialGradient(0,-10,2,0,-10,60);
    grad.addColorStop(0, colorAccent+'aa');
    grad.addColorStop(1, colorAccent+'00');
    ctx.fillStyle=grad;
    ctx.beginPath();
    ctx.arc(0,-10,60,0,Math.PI*2);
    ctx.fill();

    ctx.fillStyle=colorBody;
    ctx.beginPath();
    ctx.moveTo(-40,10);
    ctx.bezierCurveTo(-55,-30,-20,-55,10,-50);
    ctx.bezierCurveTo(35,-47,50,-25,45,0);
    ctx.bezierCurveTo(55,5,60,15,50,20);
    ctx.bezierCurveTo(40,25,35,15,30,18);
    ctx.bezierCurveTo(10,35,-25,35,-40,10);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(-40,5);
    ctx.quadraticCurveTo(-65,0,-70,-15);
    ctx.quadraticCurveTo(-55,-5,-38,-5);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(48,2);
    ctx.lineTo(62,6);
    ctx.lineTo(48,12);
    ctx.closePath();
    ctx.fillStyle=colorAccent;
    ctx.fill();

    ctx.fillStyle=colorAccent;
    for(let i=0;i<6;i++){
      const ang=i*0.9-1.2;
      const rx=Math.cos(ang)*22, ry=-20+Math.sin(ang)*18;
      ctx.beginPath();
      ctx.arc(rx,ry,2.6,0,Math.PI*2);
      ctx.fill();
    }
    ctx.fillStyle='#2a1a12';
    ctx.beginPath();
    ctx.arc(22,-28,2.4,0,Math.PI*2);
    ctx.fill();

    ctx.restore();
  }

  function frame(){
    t+=0.016;
    ctx.clearRect(0,0,W(),H());

    frostPoints.forEach((p,i)=>{
      const cx=p.x*W(), cy=p.y*H();
      const growth=0.6+0.4*Math.sin(t*0.3+i*1.7);
      drawFrost(cx,cy, Math.min(W(),H())/1000, growth, frostC+'cc');
    });

    motes.forEach(m=>{
      m.y -= m.speed;
      m.x += Math.sin(t*0.5+m.phase)*0.15;
      if(m.y< -10){ m.y=H()+10; m.x=Math.random()*W(); }
      ctx.beginPath();
      ctx.fillStyle = warm+'55';
      ctx.shadowColor=warm;
      ctx.shadowBlur=6;
      ctx.arc(m.x,m.y,m.r,0,Math.PI*2);
      ctx.fill();
      ctx.shadowBlur=0;
    });

    const birdX = W()*0.2;
    const birdY = H()*0.78;
    const bob = Math.sin(t*0.8)*6;
    const scale = Math.min(W(),H())/1000*1.3;
    drawBird(birdX, birdY, scale, bob, warm, accent);

    notes.forEach(n=>{
      const localT = (t*n.speed + n.offset*0.01)%6;
      const progress = localT/6;
      const startX = birdX+60*scale, startY = birdY-5*scale;
      const endX = W()*0.85;
      const endY = H()*0.15;
      const ctrlX = W()*0.97;
      const ctrlY = H()*0.55;
      const u=progress;
      const x = (1-u)*(1-u)*startX + 2*(1-u)*u*ctrlX + u*u*endX;
      const y = (1-u)*(1-u)*startY + 2*(1-u)*u*ctrlY + u*u*endY;
      n.trail.push({x,y});
      if(n.trail.length>10) n.trail.shift();

      const alpha = Math.sin(progress*Math.PI);
      for(let i=0;i<n.trail.length;i++){
        const pt=n.trail[i];
        const a=alpha*(i/n.trail.length)*0.5;
        ctx.beginPath();
        ctx.fillStyle = accent;
        ctx.globalAlpha = a;
        ctx.arc(pt.x,pt.y,n.size*0.5,0,Math.PI*2);
        ctx.fill();
      }
      ctx.globalAlpha=1;

      ctx.save();
      ctx.translate(x,y);
      ctx.globalAlpha=alpha;
      ctx.fillStyle=accent;
      ctx.beginPath();
      ctx.ellipse(0,0,n.size,n.size*0.75,-0.4,0,Math.PI*2);
      ctx.fill();
      ctx.strokeStyle=accent;
      ctx.lineWidth=1.4;
      ctx.beginPath();
      ctx.moveTo(n.size*0.8,-n.size*0.2);
      ctx.lineTo(n.size*0.8,-n.size*2.2);
      ctx.stroke();
      ctx.restore();
      ctx.globalAlpha=1;
    });

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
